// Parse the FastAPI response and format an intelligence summary
const res = $input.first().json;

const mode = res.mode || (res.ingestion_report ? res.ingestion_report.mode : 'unknown');
const status = res.status || 'unknown';
const recordsExtracted = res.records_extracted || 0;
const validRecords = res.valid_records || 0;
const rejectedList = res.rejected || [];
const errorsList = res.errors || [];

const actions = (res.ingestion_report && res.ingestion_report.actions) || [];
const insertedCount = actions.filter(a => a.action === 'insert').length;
const updatedCount = actions.filter(a => a.action === 'update').length;

const summaryText = `
========================================
🇮🇳 IndiaTechIntelligence Collection Run
========================================
Status: ${status.toUpperCase()}
Mode: ${mode.toUpperCase()}
Candidates Scraped: ${recordsExtracted}
Valid India Records: ${validRecords}
Planned / Written Inserts: ${insertedCount}
Planned / Written Updates: ${updatedCount}
Rejected Records: ${rejectedList.length}
Errors Encountered: ${errorsList.length}

Top Extracted Jobs:
${actions.slice(0, 5).map(a => `• [${a.company}] ${a.title} (${a.location || 'India'}) -> ${a.action.toUpperCase()}`).join('\n') || 'None'}

${rejectedList.length > 0 ? 'Sample Rejections:\n' + rejectedList.slice(0, 3).map(r => `• ${r.title}: ${r.errors.join(', ')}`).join('\n') : ''}
========================================
`;

return [{
  json: {
    status,
    mode,
    recordsExtracted,
    validRecords,
    insertedCount,
    updatedCount,
    rejectedCount: rejectedList.length,
    errorsCount: errorsList.length,
    summaryText,
    raw_response: res
  }
}];
